function cursorConfigDir() {
  const e = process.env.CURSOR_CONFIG_DIR;
  if (e && e.trim()) return e;
  const x = process.env.XDG_CONFIG_HOME;
  if (x && x.trim()) return path.join(x, 'cursor');
  return path.join(HOME, '.cursor');
}
function makeMaxConfigDir(model) {
  const cfg = JSON.parse(fs.readFileSync(path.join(cursorConfigDir(), 'cli-config.json'), 'utf8'));
  cfg.maxMode = true;
  if (model) {
    cfg.selectedModel = { modelId: String(model), parameters: [] };
    cfg.model = Object.assign({}, cfg.model, { modelId: String(model), displayModelId: String(model), maxMode: true });
  } else if (cfg.model) { cfg.model.maxMode = true; }
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'fanbox-cursor-'));
  fs.writeFileSync(path.join(dir, 'cli-config.json'), JSON.stringify(cfg), 'utf8');
  return dir;
}
function rmTmpDir(dir) { if (dir) { try { fs.rmSync(dir, { recursive: true, force: true }); } catch { /* */ } } }

