markMaxOnly(id) {
  if (!id) return;
  const s = this.maxOnlySet(); if (s.has(id)) return;
  s.add(id); try { localStorage.setItem('fb_chat_maxonly', JSON.stringify([...s])); } catch { /* 配额满则静默 */ }
  this._modelsLoaded = false; this.loadCursorModels(); // 重建选择器，剔掉该模型
